package local.skyfamily;
import android.graphics.*;import android.text.*;import android.view.*;import android.widget.*;import org.json.JSONObject;import java.util.*;
final class BookReader extends LinearLayout {
 final BooksActivity host;final JSONObject book;final BookData data;final String key;TextView pageText,indicator;int chapter,offset,page=0,generation=0,font;ArrayList<Integer> starts=new ArrayList<>();boolean closed=false;
 BookReader(BooksActivity h,JSONObject record,BookData loaded){super(h);host=h;book=record;data=loaded;key="book."+book.optString("id");chapter=Math.max(0,Math.min(data.chapters.size()-1,h.prefs.getInt(key+".chapter",0)));offset=h.prefs.getInt(key+".offset",0);font=h.prefs.getInt("books.font",22);setOrientation(1);setBackgroundColor(0xff10192a);LinearLayout top=new LinearLayout(h);addView(top,new LinearLayout.LayoutParams(-1,h.dp(52)));control(top,"Bookshelf",()->h.bookshelf());control(top,"Chapters",()->chapters());control(top,"Rotate",()->h.screenRotation());TextView title=new TextView(h);title.setText(book.optString("title"));title.setTextColor(h.muted);title.setTextSize(15);title.setPadding(h.dp(18),h.dp(5),h.dp(18),h.dp(5));title.setMaxLines(1);addView(title);pageText=new TextView(h){protected void onSizeChanged(int w,int height,int oldw,int oldh){super.onSizeChanged(w,height,oldw,oldh);if(w!=oldw||height!=oldh)post(()->paginate());}};pageText.setTextColor(0xfff0eadf);pageText.setTypeface(Typeface.SERIF);pageText.setTextSize(font);pageText.setIncludeFontPadding(false);pageText.setLineSpacing(0,1.25f);pageText.setPadding(h.dp(20),h.dp(14),h.dp(20),h.dp(14));addView(pageText,new LinearLayout.LayoutParams(-1,0,1));indicator=new TextView(h);indicator.setText("Preparing pages...");indicator.setTextColor(h.accent);indicator.setTextSize(14);indicator.setGravity(Gravity.CENTER);addView(indicator);LinearLayout bottom=new LinearLayout(h);addView(bottom,new LinearLayout.LayoutParams(-1,h.dp(56)));control(bottom,"Previous",()->previous());control(bottom,"A-",()->resize(-2));control(bottom,"A+",()->resize(2));control(bottom,"Next",()->next());pageText.setOnTouchListener(new View.OnTouchListener(){float x;public boolean onTouch(View v,MotionEvent e){if(e.getAction()==0){x=e.getX();return true;}if(e.getAction()==1){float delta=e.getX()-x;if(Math.abs(delta)>h.dp(45)){if(delta<0)next();else previous();}else if(e.getX()>v.getWidth()*.7f)next();else if(e.getX()<v.getWidth()*.3f)previous();return true;}return true;}});}
 void control(LinearLayout row,String text,Runnable action){TextView t=new TextView(host);t.setText(text);t.setTextColor(host.fg);t.setTextSize(16);t.setGravity(Gravity.CENTER);row.addView(t,new LinearLayout.LayoutParams(0,-1,1));t.setOnClickListener(v->action.run());}
 void resize(int delta){font=Math.max(14,Math.min(36,font+delta));host.prefs.edit().putInt("books.font",font).apply();pageText.setTextSize(font);paginate();}
 void chapters(){String[] names=new String[data.chapters.size()];for(int i=0;i<names.length;i++)names[i]="Chapter "+(i+1);new android.app.AlertDialog.Builder(host).setTitle("Book chapters / text sections").setSingleChoiceItems(names,chapter,(dialog,index)->{chapter=index;offset=0;starts.clear();paginate();dialog.dismiss();}).setNegativeButton("Close",null).show();}
 void paginate(){if(closed||pageText==null)return;int width=pageText.getWidth()-pageText.getPaddingLeft()-pageText.getPaddingRight(),height=pageText.getHeight()-pageText.getPaddingTop()-pageText.getPaddingBottom();if(width<30||height<30)return;final int stamp=++generation,currentChapter=chapter,currentOffset=offset;final String text=data.chapters.get(currentChapter);final TextPaint paint=new TextPaint(Paint.ANTI_ALIAS_FLAG);paint.setTypeface(Typeface.SERIF);paint.setTextSize(font*getResources().getDisplayMetrics().scaledDensity);indicator.setText("Preparing pages...");host.work(()->{StaticLayout layout=new StaticLayout(text,paint,width,Layout.Alignment.ALIGN_NORMAL,1.25f,0,false);ArrayList<Integer> positions=new ArrayList<>();int line=0;while(line<layout.getLineCount()){positions.add(layout.getLineStart(line));int end=line,top=layout.getLineTop(line);while(end<layout.getLineCount()&&layout.getLineBottom(end)-top<=height)end++;line=Math.max(line+1,end);}if(positions.isEmpty())positions.add(0);positions.add(text.length());host.ui.post(()->{if(closed||stamp!=generation||currentChapter!=chapter)return;starts=positions;page=0;int safe=Math.min(currentOffset,text.length());while(page+1<starts.size()-1&&starts.get(page+1)<=safe)page++;display();});});}
 void display(){if(starts.size()<2)return;String text=data.chapters.get(chapter);offset=starts.get(page);pageText.setText(text.substring(offset,starts.get(page+1)));store();}
 int percent(){long total=0,before=0;for(int i=0;i<data.chapters.size();i++){long length=data.chapters.get(i).length();total+=length;if(i<chapter)before+=length;}int end=starts.size()>page+1?starts.get(page+1):offset;return total==0?0:(int)Math.min(100,(before+end)*100/total);}
 void store(){if(closed)return;int percentage=percent();String label="Chapter "+(chapter+1)+"/"+data.chapters.size()+" / Page "+(page+1)+"/"+Math.max(1,starts.size()-1)+" / "+percentage+"%";if(indicator!=null&&starts.size()>=2)indicator.setText(label);host.prefs.edit().putInt(key+".chapter",chapter).putInt(key+".offset",offset).putInt(key+".percent",percentage).putString(key+".label",label).putLong(key+".last",System.currentTimeMillis()).putString("books.last",book.optString("id")).apply();}
 void next(){if(starts.size()<2)return;if(page<starts.size()-2){page++;display();}else if(chapter<data.chapters.size()-1){chapter++;offset=0;starts.clear();paginate();}else host.toast("End of book");}
 void previous(){if(starts.size()<2)return;if(page>0){page--;display();}else if(chapter>0){chapter--;offset=Integer.MAX_VALUE;starts.clear();paginate();}}
 protected void onDetachedFromWindow(){store();closed=true;generation++;super.onDetachedFromWindow();}
}
